  animate('.dot',[{scale:0},{scale:1}],520,1080,EXPO)
  animate('.track i',[{scale:'0 1'},{scale:'1 1'}],820,1120,EXPO)
  rise(.num[0],920,860);  rise(.num[1],990,860)
