    :root{--u: min(100vw / 1240, 100vh / 820); --pad: 46}
    @supports (height:100dvh){:root{--u: min(100vw / 1240, 100dvh / 820)}}
    @media (max-height: 520px){        /* rotated phone: landscape but very short */
