@font-face{font-family:"PX Sans";font-weight:400;font-display:block;src:url(assets/px-sans-400.woff2) format("woff2")}
@font-face{font-family:"PX Sans";font-weight:700;font-display:block;src:url(assets/px-sans-700.woff2) format("woff2")}
:root{
  --bg:#3a5462;
  --ink:#ffffff;
  --panel:#000000;
  --ring:rgba(255,255,255,.5);
  --vw:100vw; --vh:100vh;
  --sc:max(calc(var(--vw) / 1280), calc(var(--vh) / 800));
  --u:clamp(.72px, min(calc(var(--vw) / 1280), calc(var(--vh) / 800)), 3px);
  --mono:"PX Mono","Roboto Mono",ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;
  --sans:"PX Sans",Inter,"Helvetica Neue",Arial,system-ui,sans-serif;
}
