.copy--tl{left:calc(34.5 * var(--u));top:calc(46.6 * var(--u))}
.copy--tr{right:calc(45 * var(--u));top:calc(39 * var(--u));text-align:right}
.copy--bl{left:calc(34.5 * var(--u));bottom:calc(39.5 * var(--u))}
.copy--br{right:calc(45 * var(--u));bottom:calc(39.5 * var(--u));text-align:right}
.nav{position:absolute;top:calc(29.5 * var(--u));left:calc(50% - 5 * var(--u));transform:translateX(-50%);
  width:calc(300.5 * var(--u));height:calc(53.7 * var(--u));background:var(--panel);display:flex;align-items:center;justify-content:space-between;
  padding:0 calc(15 * var(--u)) 0 calc(9 * var(--u))}
.logo{display:block;color:var(--ink);text-decoration:none;font:700 calc(39 * var(--u))/1 var(--sans);letter-spacing:-0.01em;transform:translateY(calc(-5 * var(--u)))}
