  .copy--tr{right:calc(20 * var(--u));top:calc(96 * var(--u))}
  .copy--bl{left:calc(20 * var(--u));bottom:calc(24 * var(--u))}
  .ctas{left:calc(20 * var(--u));bottom:calc(76 * var(--u))}
  .copy--br{right:calc(20 * var(--u));bottom:calc(24 * var(--u))}
}
@media (prefers-reduced-motion:reduce){*{transition:none!important}}
.ln{display:block}
.ln>span{display:inline-block}
.px-intro .rings path{stroke-dasharray:0 100000}
.px-intro .title{overflow:hidden}
