.px-intro .nav{clip-path:inset(0 50% 0 50%)}
.px-intro .logo,.px-intro .menu{opacity:0}
.px-intro .btn{clip-path:inset(0 100% 0 0)}
.px-intro .lbl{opacity:0}
</style>
